// Oversold on top, overbought below.
const row = (s) => `${(s.symbol ?? '?').padEnd(10)} RSI ${String(s.rsi ?? 'n/a').padEnd(6)} ${String(s.price ?? 'n/a').padEnd(9)} ${s.name ?? ''}`;
const oversold = $('Oversold Stocks').all().map(i => i.json);
const overbought = $('Overbought Stocks').all().map(i => i.json);

const lines = [
  `Stocklake screener digest, ${new Date().toDateString()}`,
  '',
  `Oversold (${oversold.length}), RSI low:`,
  ...(oversold.length ? oversold.map(row) : ['  none']),
  '',
  `Overbought (${overbought.length}), RSI high:`,
  ...(overbought.length ? overbought.map(row) : ['  none']),
];
return [{ json: { subject: `Screener digest: ${oversold.length} oversold, ${overbought.length} overbought`, body: lines.join('\n') } }];
